// Injects the foreground-service plugin sources + manifest permissions into the Android project
// generated by `npx cap add android`. Run after `cap add android` / `cap sync`.
// Idempotent: re-running is safe.
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const mobileRoot = join(dirname(fileURLToPath(import.meta.url)), '..')
const androidDir = join(mobileRoot, 'android')
if (!existsSync(androidDir)) {
  console.error('android/ not found - run "npx cap add android" first')
  process.exit(1)
}

const overridesDir = join(mobileRoot, 'android-overrides')
const javaRoot = join(androidDir, 'app/src/main/java')

const findMainActivity = (dir) => {
  for (const entry of readdirSync(dir)) {
    const p = join(dir, entry)
    if (statSync(p).isDirectory()) {
      const found = findMainActivity(p)
      if (found) {
        return found
      }
    }
    else if (entry === 'MainActivity.java' || entry === 'MainActivity.kt') {
      return p
    }
  }
  return null
}

const mainPath = findMainActivity(javaRoot)
if (!mainPath) {
  console.error('MainActivity not found under', javaRoot)
  process.exit(1)
}

const targetDir = dirname(mainPath)
const pkg = readFileSync(mainPath, 'utf8').match(/package\s+([\w.]+)/)[1]

// Remove the generated MainActivity (java or kt) so our version is the only one.
rmSync(mainPath)

for (const file of ['MainActivity.java', 'ForegroundServicePlugin.java', 'PlaybackService.java']) {
  const src = readFileSync(join(overridesDir, file), 'utf8').replaceAll('__PACKAGE__', pkg)
  writeFileSync(join(targetDir, file), src)
}

// Instrumentation test (the background-audio gate). Lives under app/src/androidTest mirroring the
// app package path.
const pkgPath = pkg.replaceAll('.', '/')
const androidTestDir = join(androidDir, 'app/src/androidTest/java', pkgPath)
mkdirSync(androidTestDir, { recursive: true })
const testSrc = readFileSync(join(overridesDir, 'androidTest/ForegroundServiceTest.java'), 'utf8').replaceAll('__PACKAGE__', pkg)
writeFileSync(join(androidTestDir, 'ForegroundServiceTest.java'), testSrc)

// uiautomator is needed by the instrumentation test; add it if the template lacks it.
const buildGradlePath = join(androidDir, 'app/build.gradle')
let buildGradle = readFileSync(buildGradlePath, 'utf8')
if (!buildGradle.includes('uiautomator')) {
  buildGradle = buildGradle.replace(
    /dependencies\s*{/,
    'dependencies {\n    androidTestImplementation "androidx.test.uiautomator:uiautomator:2.3.0"',
  )
  writeFileSync(buildGradlePath, buildGradle)
}

// Patch AndroidManifest: permissions + service declaration.
const manifestPath = join(androidDir, 'app/src/main/AndroidManifest.xml')
let manifest = readFileSync(manifestPath, 'utf8')

const permissions = [
  'android.permission.FOREGROUND_SERVICE',
  'android.permission.FOREGROUND_SERVICE_MEDIA_PLAYBACK',
  'android.permission.POST_NOTIFICATIONS',
]
let permXml = ''
for (const perm of permissions) {
  if (!manifest.includes(perm)) {
    permXml += `    <uses-permission android:name="${perm}" />\n`
  }
}
if (permXml) {
  manifest = manifest.replace('<application', `${permXml}\n    <application`)
}

if (!manifest.includes('PlaybackService')) {
  const service = '        <service android:name=".PlaybackService" android:foregroundServiceType="mediaPlayback" android:exported="false" />\n'
  manifest = manifest.replace('</application>', `${service}    </application>`)
}
writeFileSync(manifestPath, manifest)

console.log(`Applied Android overrides for package ${pkg}`)
